          binding.pattern = binding.pattern.with(\.trailingTrivia, [])
        }
        conditionCopy.condition = .optionalBinding(binding)
      }
      return conditionCopy
    }
    return node.with(\.conditions, ConditionElementListSyntax(newConditions))
  }
